# Custom Promise

## Scenario

You are reviewing a custom Promise implementation designed to mimic native JavaScript Promise behavior. The following code defines a basic CustomPromise class:

```javascript
class CustomPromise {
  constructor(executor) {
    this.state = 'pending';
    this.value = null;
    this.callbacks = [];

    const resolve = (value) => {
      if (this.state === 'pending') {
        this.state = 'fulfilled';
        this.value = value;
        this.callbacks.forEach(cb => cb());
      }
    };

    const reject = (reason) => {
      if (this.state === 'pending') {
        this.state = 'rejected';
        this.value = reason;
        this.callbacks.forEach(cb => cb());
      }
    };

    try {
      executor(resolve, reject);
    } catch (error) {
      reject(error);
    }
  }

  then(onFulfilled, onRejected) {
    return new CustomPromise((resolve, reject) => {
      const handle = () => {
        try {
          if (this.state === 'fulfilled') {
            const result = onFulfilled(this.value);
            resolve(result);
          } else if (this.state === 'rejected') {
            const result = onRejected(this.value);
            resolve(result);
          }
        } catch (error) {
          reject(error);
        }
      };
      this.callbacks.push(handle);
    });
  }
}

const promise = new CustomPromise((resolve, reject) => {
  resolve(5);
});

promise.then(
  (value) => {
    throw new Error('Handler error');
  },
  (error) => {
    console.log('Error handler called');
  }
);
```

