# Throttling

## Scenario

You are reviewing the following code that implements a custom throttling mechanism for an API data-fetching system:

```javascript
async function fetchData(url) {
  return fetch(url).then(res => res.json());
}

function createThrottledFetcher(maxConcurrent) {
  let activeRequests = 0;
  const queue = [];

  async function processQueue() {
    while (queue.length > 0 && activeRequests < maxConcurrent) {
      activeRequests++;
      const { url, resolve, reject } = queue.shift();

      try {
        const data = await fetchData(url);
        resolve(data);
      } catch (error) {
        reject(error);
      } finally {
        activeRequests--;
        processQueue();
      }
    }
  }

  return function throttled(url) {
    return new Promise((resolve, reject) => {
      queue.push({ url, resolve, reject });
      processQueue();
    });
  };
}

const fetcher = createThrottledFetcher(3);
fetcher('/api/users').then(data => console.log(data));
fetcher('/api/posts').then(data => console.log(data));
fetcher('/api/comments').then(data => console.log(data));
fetcher('/api/tags').then(data => console.log(data));
```

