  useLayoutEffect(() => {
    document.title = `Count: ${count}`;
  }, []);
  return (
    <div>
      <p>Count: {count}</p>
      <button onClick={() => setCount(count + 1)}>Increment</button>
    </div>
  );
}
```

D)
```javascript
function Counter() {
  const count = useRef(0);
  useEffect(() => {
    document.title = `Count: ${count.current}`;
  }, [count]);
  return (
    <div>
      <p>Count: {count.current}</p>
