```java
import javax.xml.xpath.*;
import org.w3c.dom.*;
import org.xml.sax.InputSource;
import java.io.StringReader;

public class UserAuthenticator {
    private DocumentBuilder docBuilder;
    private XPath xpath;

    public UserAuthenticator(DocumentBuilder db, XPath xp) {
        this.docBuilder = db;
        this.xpath = xp;
    }

    public User getUserByUsername(String username, String xmlData) 
            throws XPathExpressionException {

        String xpathQuery = "//user[username='" + username + "']";
        XPathExpression expr = xpath.compile(xpathQuery);

        Document doc = docBuilder.parse(
            new InputSource(new StringReader(xmlData))
        );

        NodeList nodes = (NodeList) expr.evaluate(doc, XPathConstants.NODESET);

        if (nodes.getLength() > 0) {
            Element userElement = (Element) nodes.item(0);
            return new User(
                userElement.getElementsByTagName("username").item(0).getTextContent(),
                userElement.getElementsByTagName("email").item(0).getTextContent()
            );
        }
        return null;
    }
}
```

